insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_88_v1'
from (values
('127.689.d.1.A',3,'A start-up avoids buying servers and instead rents computing power by the hour. One benefit of this move is:','["paying only for what it uses", "never needing the internet", "owning all the hardware", "guaranteed zero downtime"]'::jsonb,0,'Pay-as-you-go lowers upfront cost.','original'),
('127.689.d.1.A',4,'A risk a company accepts when moving its data to a cloud provider is:','["being unable to scale", "depending on the provider''s availability and security", "having to buy more cables", "losing all internet access"]'::jsonb,1,'Providers become a dependency.','original'),
('127.689.d.1.B',3,'Renting virtual servers, storage and networks from a provider is called:','["a desktop suite", "software as a service", "infrastructure as a service (IaaS)", "a local network"]'::jsonb,2,'IaaS supplies raw computing resources.','original'),
('127.689.d.1.B',4,'Using a web-based email service you do not install or maintain is an example of:','["on-premises hosting", "infrastructure as a service", "a private data center", "software as a service (SaaS)"]'::jsonb,3,'SaaS delivers finished applications.','original'),
('127.689.d.1.C',3,'A school wants a cloud plan for a yearbook site that is busy only in May. The plan should expect:','["seasonal spikes in usage and cost", "no usage at all", "unlimited free service", "constant flat usage"]'::jsonb,0,'Usage plans reflect demand patterns.','original'),
('127.689.d.1.C',4,'In a case-study usage plan, estimating monthly storage, compute hours and data transfer helps the business to:','["choose a logo", "predict its cloud bill", "avoid backups", "skip security"]'::jsonb,1,'Estimates become cost forecasts.','original'),
('127.689.d.1.D',3,'A cloud region is best described as:','["a single hard drive", "a billing account", "a geographic area containing cloud data centers", "a type of password"]'::jsonb,2,'Regions are locations of facilities.','original'),
('127.689.d.1.D',4,'An edge location mainly exists to:','["train new employees", "replace regions entirely", "store all billing data", "cache content closer to users for faster delivery"]'::jsonb,3,'Edge sites reduce latency.','original'),
('127.689.d.1.E',3,'Amazon Web Services, Microsoft Azure and Google Cloud are each a:','["major cloud computing provider", "web browser", "programming language", "operating system"]'::jsonb,0,'They are leading cloud platforms.','original'),
('127.689.d.1.E',4,'When comparing cloud providers for a school project, a team should weigh price, services offered and:','["the provider''s logo", "support and data location options", "the length of the name", "the color of the website"]'::jsonb,1,'Comparison uses practical criteria.','original'),
('127.689.d.2.A',3,'A cloud service that stores files and lets you open them from any device provides:','["a game console", "a power supply", "object or file storage", "a printer driver"]'::jsonb,2,'Cloud storage syncs across devices.','original'),
('127.689.d.2.A',4,'A managed database service is useful because the provider handles:','["designing your logo", "writing your queries", "choosing your data", "patching, backups and hardware upkeep"]'::jsonb,3,'Managed services reduce admin work.','original'),
('127.689.d.2.B',3,'A cloud console is a web interface used to:','["create and manage cloud resources", "play videos", "edit photos", "print documents"]'::jsonb,0,'Consoles control services.','original'),
('127.689.d.2.B',4,'In a console, a beginner who wants to start a virtual server would look for the service that provides:','["only email", "compute instances", "only billing statements", "only fonts"]'::jsonb,1,'Compute services launch servers.','original'),
('127.689.d.2.C',3,'A streaming video company uses the cloud to handle:','["only paper records", "a single office", "millions of viewers at the same time", "only one viewer"]'::jsonb,2,'Cloud scales for large audiences.','original'),
('127.689.d.2.C',4,'A hospital storing scans in the cloud must still follow rules about:','["emoji use", "wallpaper", "font choices", "protecting patient privacy"]'::jsonb,3,'Healthcare data has privacy laws.','original'),
('127.689.d.2.D',3,'The domain name system (DNS) turns a name like example.com into a:','["numeric IP address", "screen color", "file size", "password"]'::jsonb,0,'DNS translates names to addresses.','original'),
('127.689.d.2.D',4,'If DNS is not working, a user may still reach a site by typing its:','["favorite color", "IP address directly", "email password", "username"]'::jsonb,1,'The numeric address bypasses name lookup.','original'),
('127.689.d.2.E',3,'An object storage bucket is a container used to hold:','["only processors", "only monitors", "files such as images and documents", "only passwords"]'::jsonb,2,'Buckets store objects.','original'),
('127.689.d.2.E',4,'Bucket names in many cloud services must be:','["blank", "a single letter only", "identical to others", "unique within the service"]'::jsonb,3,'Global uniqueness avoids conflicts.','original'),
('127.689.d.2.F',3,'A content delivery network (CDN) makes websites faster by:','["serving copies of content from servers near the visitor", "slowing the server", "blocking visitors", "deleting images"]'::jsonb,0,'Nearby copies reduce delay.','original'),
('127.689.d.2.F',4,'A CDN also helps a site survive a traffic surge because it:','["adds more ads", "spreads requests across many servers", "shuts the site down", "lowers image quality only"]'::jsonb,1,'Distribution relieves the origin.','original'),
('127.689.d.2.G',3,'To speed up a site with a CDN distribution, an admin points the distribution at the site''s:','["email list", "paper menu", "origin (the source of its content)", "tax records"]'::jsonb,2,'The origin supplies the files.','original'),
('127.689.d.2.G',4,'After attaching a distribution to a website, visitors should reach the site through the distribution''s:','["backup file", "old password", "billing page", "domain or alias name"]'::jsonb,3,'The new endpoint routes through edge locations.','original'),
('127.689.d.2.H',3,'Block storage works like a:','["hard drive attached to a server", "text message", "printed book", "video call"]'::jsonb,0,'Blocks act as disk volumes.','original'),
('127.689.d.2.H',4,'Compared with object storage, block storage is better for:','["storing billions of backups cheaply", "an operating system or database that needs fast disk access", "archiving old documents", "hosting a static photo gallery"]'::jsonb,1,'Low-latency volumes suit active workloads.','original'),
('127.689.d.2.I',3,'A company needs to keep seven years of old records at the lowest cost, rarely opened. The best choice is:','["a database cache", "fast block storage", "archival storage", "a local USB drive only"]'::jsonb,2,'Archival tiers are cheapest for rare access.','original'),
('127.689.d.2.I',4,'A busy database needs very fast reads and writes. The best virtual storage is:','["a printed ledger", "cold archive storage", "a static website bucket", "high-performance block storage"]'::jsonb,3,'Active databases need low latency.','original'),
('127.689.d.2.J',3,'Before using a new block storage volume, an admin must choose its size and:','["the availability zone it lives in", "its username", "its favorite color", "its shoe size"]'::jsonb,0,'Volumes belong to a zone.','original'),
('127.689.d.2.J',4,'A block storage volume created in one availability zone cannot normally be attached to a server in:','["the same availability zone", "a different availability zone", "its own zone", "the same region and zone"]'::jsonb,1,'Zone boundaries limit attachment.','original'),
('127.689.d.2.K',3,'Attaching a volume to a virtual computing instance makes the volume:','["disappear", "a printer", "available to the instance as a disk", "a website"]'::jsonb,2,'Attachment connects storage to compute.','original'),
('127.689.d.2.K',4,'After attaching a new volume, the instance''s operating system usually still must:','["change the region", "delete the volume", "rename the cloud", "format and mount the volume before use"]'::jsonb,3,'A blank disk needs a file system.','original'),
('127.689.d.2.L',3,'A simple website on a virtual computing instance needs web server software and:','["the site''s files", "a game controller", "a camera", "a printer"]'::jsonb,0,'The server must serve content.','original'),
('127.689.d.2.L',4,'To let visitors reach the instance''s website, the instance''s firewall rules must allow inbound:','["no traffic at all", "web traffic on the HTTP/HTTPS ports", "only printer traffic", "only email traffic"]'::jsonb,1,'Ports must be open for browsers.','original'),
('127.689.d.3.A',3,'A best practice for identity and access management (IAM) is giving each user:','["none of the permissions", "every permission", "only the permissions needed for their job", "the owner''s password"]'::jsonb,2,'Least privilege reduces risk.','original'),
('127.689.d.3.A',4,'Turning on multi-factor authentication for IAM users helps protect accounts if a:','["screen is dim", "mouse is slow", "fan is loud", "password is stolen"]'::jsonb,3,'A second factor blocks stolen passwords.','original'),
('127.689.d.3.B',3,'Strong cloud security matters to society because breaches of cloud-stored data can expose many people''s:','["personal information", "wallpaper", "desk setups", "playlist colors"]'::jsonb,0,'Breaches harm individuals.','original'),
('127.689.d.3.B',4,'As more schools and hospitals rely on cloud services, a major societal concern is protecting:','["font styles", "privacy and trust in digital records", "emoji sets", "screensavers"]'::jsonb,1,'Trust depends on security.','original'),
('127.689.d.3.C',3,'In cloud security, a user is:','["a firewall", "a region", "an identity for a person or app that can sign in", "a storage price"]'::jsonb,2,'Users are identities.','original'),
('127.689.d.3.C',4,'A policy in cloud security is a document that:','["prints invoices", "lists user birthdays", "draws a network map", "defines which actions are allowed or denied"]'::jsonb,3,'Policies set permissions.','original'),
('127.689.d.3.D',3,'After a scan finds an outdated web server, the first step in a vulnerability process is to:','["identify and rank the risk", "ignore it", "announce passwords", "delete the server"]'::jsonb,0,'Assess before fixing.','original'),
('127.689.d.3.D',4,'Applying a patch and then rescanning a web server is done to:','["add more bugs", "confirm the vulnerability is fixed", "slow the site", "remove logs"]'::jsonb,1,'Verification closes the loop.','original'),
('127.689.d.3.E',3,'A cloud security lapse such as a publicly open storage bucket is best fixed by:','["renaming it only", "making it larger", "restricting access to authorized users", "adding more files"]'::jsonb,2,'Closing public access stops exposure.','original'),
('127.689.d.3.E',4,'After a security lapse is fixed, a team should also review logs to learn:','["which logo to use", "what to rename the bucket", "how to change fonts", "whether anyone accessed the data"]'::jsonb,3,'Logs show if data was exposed.','original'),
('127.689.d.3.F',3,'A company wants to block common web attacks like SQL injection on its site. It should choose a:','["web application firewall", "email client", "file backup service", "video encoder"]'::jsonb,0,'A WAF filters malicious requests.','original'),
('127.689.d.3.F',4,'A team needs to detect unusual login behavior across accounts. The best cloud service type is:','["DNS hosting", "threat detection monitoring", "image resizing", "file compression"]'::jsonb,1,'Threat detection flags anomalies.','original'),
('127.689.d.3.G',3,'A text alert for a suspicious IAM event is often sent through a:','["calculator", "printer", "notification service", "spreadsheet"]'::jsonb,2,'Notification services send messages.','original'),
('127.689.d.3.G',4,'To be alerted when someone signs in as the root user, an admin sets up an event rule that triggers a:','["price change", "file deletion", "system reboot", "text message notification"]'::jsonb,3,'Rules connect events to alerts.','original'),
('127.689.d.3.H',3,'Monitoring services mainly show:','["how resources are performing right now", "old tax forms", "family photos", "menu options"]'::jsonb,0,'Monitoring tracks metrics.','original'),
('127.689.d.3.H',4,'Logging services differ from monitoring in that logs mainly record:','["only storage prices", "a detailed history of events and actions", "only the current CPU number", "only user birthdays"]'::jsonb,1,'Logs keep records for review.','original'),
('127.689.d.4.A',3,'A system that records thousands of small bank deposits as they happen is built for:','["online analytical processing", "image printing", "online transactional processing (OLTP)", "video editing"]'::jsonb,2,'OLTP handles many small transactions.','original'),
('127.689.d.4.A',4,'A system that scans years of sales data to find trends is built for:','["transactional entry", "name lookups", "password resets", "online analytical processing (OLAP)"]'::jsonb,3,'OLAP supports analysis of large data sets.','original'),
('127.689.d.4.B',3,'Caching data helps an application because frequently used data is kept:','["in a fast place close to the app", "offline forever", "in a locked safe", "on paper"]'::jsonb,0,'Caches shorten access time.','original'),
('127.689.d.4.B',4,'A cache can also lower costs by reducing the number of:','["passwords", "slow requests to the main database", "pixels", "users"]'::jsonb,1,'Fewer database hits save resources.','original'),
('127.689.d.4.C',3,'A load balancer attached to a web page sends each visitor to:','["a printer", "the same broken server", "one of several healthy servers", "nowhere"]'::jsonb,2,'It distributes traffic.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_88_v1'
from (values
('127.689.d.4.C',4,'To attach a load balancer, an admin registers the web servers as its:','["invoices", "passwords", "logos", "targets"]'::jsonb,3,'Targets receive forwarded requests.','original'),
('127.689.d.4.D',3,'One benefit of load balancing is that if a server fails, traffic:','["is routed to the remaining servers", "is deleted", "doubles the bill", "stops completely"]'::jsonb,0,'Health checks reroute traffic.','original'),
('127.689.d.4.D',4,'Load balancing improves availability because no single server:','["is ever monitored", "has to carry all the visitors", "is ever turned on", "is ever updated"]'::jsonb,1,'Spreading load prevents overload.','original'),
('127.689.d.4.E',3,'To evaluate a load balancer''s performance, an admin reviews metrics such as:','["paper usage", "font size", "request count and response time", "office hours"]'::jsonb,2,'Metrics show how it behaves.','original'),
('127.689.d.4.E',4,'If a load balancer''s response time keeps rising during busy hours, the admin should consider:','["closing the console", "deleting its logs", "removing health checks", "adding more servers behind it"]'::jsonb,3,'More capacity eases load.','original'),
('127.689.d.4.F',3,'Platform as a service (PaaS) lets a developer build an app without managing:','["the underlying servers and operating system", "any users", "any code", "any ideas"]'::jsonb,0,'PaaS hides infrastructure.','original'),
('127.689.d.4.F',4,'A developer deploys a web app by uploading code to a PaaS. The platform then handles:','["naming the company", "scaling and running the app", "writing the code", "choosing the colors"]'::jsonb,1,'The platform runs the code.','original'),
('127.689.d.4.G',3,'Infrastructure as code means building cloud resources using:','["paper forms", "screwdrivers", "text templates that describe them", "phone calls"]'::jsonb,2,'Templates define infrastructure.','original'),
('127.689.d.4.G',4,'A benefit of using a template to build a virtual private cloud (VPC) is that it:','["needs no testing", "skips security", "makes each network different", "creates the same network again and again reliably"]'::jsonb,3,'Templates are repeatable.','original'),
('127.689.d.5.A',3,'Machine learning is a method in which computers:','["learn patterns from data to make predictions", "follow only fixed rules", "cannot improve", "need no data"]'::jsonb,0,'ML learns from examples.','original'),
('127.689.d.5.A',4,'One societal concern about machine learning systems is that they can:','["run without electricity", "reflect bias found in their training data", "never make errors", "always be perfectly fair"]'::jsonb,1,'Biased data leads to biased results.','original'),
('127.689.d.5.B',3,'A farm uses cloud-connected sensors to water crops only when soil is dry. This is an emerging-technology use case called:','["a word processor", "a paper log", "the Internet of Things (IoT)", "a floppy disk"]'::jsonb,2,'IoT devices report data to the cloud.','original'),
('127.689.d.5.B',4,'A store uses cloud AI to predict which products will sell out next week. The use case is:','["font design", "wallpaper choice", "typing practice", "demand forecasting"]'::jsonb,3,'Forecasting uses cloud-scale analysis.','original'),
('127.689.d.5.C',3,'A value proposition of the cloud for a small business is that it can:','["use powerful tools without buying hardware", "avoid all risk", "stop paying forever", "skip planning"]'::jsonb,0,'Cloud lowers entry cost.','original'),
('127.689.d.5.C',4,'Assessing the value of moving to the cloud means comparing its benefits against its:','["desk sizes", "costs and risks", "font options", "logos"]'::jsonb,1,'Value is net benefit.','original'),
('127.689.d.5.D',3,'A cloud service that scans stored files for sensitive data like credit card numbers helps to:','["print posters", "edit audio", "analyze and protect data", "design logos"]'::jsonb,2,'Data-protection services find exposures.','original'),
('127.689.d.5.D',4,'A cloud network service that watches traffic and flags unusual patterns helps to:','["bake bread", "choose colors", "grade quizzes", "manage and secure networks"]'::jsonb,3,'Network tools monitor and protect.','original'),
('127.689.d.5.E',3,'Blockchain is a shared record that stores data in linked:','["blocks that are hard to change", "paper folders", "erasable notes", "private diaries"]'::jsonb,0,'Blocks are chained with hashes.','original'),
('127.689.d.5.E',4,'A benefit of blockchain is that a recorded transaction is:','["hidden from all parties", "very difficult to alter without detection", "random each time", "easy for anyone to erase"]'::jsonb,1,'Immutability builds trust.','original'),
('127.689.d.5.F',3,'A cloud development kit lets developers describe cloud infrastructure using:','["sound waves", "paper maps", "a familiar programming language", "finger paint"]'::jsonb,2,'Kits turn code into resources.','original'),
('127.689.d.5.F',4,'A software development kit (SDK) for a cloud service mainly provides:','["office furniture", "printer paper", "hardware cables", "libraries and tools to call the service from code"]'::jsonb,3,'SDKs simplify service use.','original'),
('127.689.d.5.G',3,'A software development framework can model an application''s resources and then:','["provision them in the cloud automatically", "ignore them", "delete them at random", "print them"]'::jsonb,0,'Frameworks generate templates and deploy.','original'),
('127.689.d.5.G',4,'Before provisioning a modeled application, the framework can show a preview so the developer can:','["skip the review", "review the changes it will make", "remove the preview", "hide the changes"]'::jsonb,1,'Previews prevent surprises.','original'),
('127.689.d.6.A',3,'In the shared responsibility model, the provider is responsible for:','["the customer''s passwords", "the customer''s staff training", "security of the cloud infrastructure itself", "the customer''s data choices"]'::jsonb,2,'Providers secure facilities and hardware.','original'),
('127.689.d.6.A',4,'In the shared responsibility model, the customer is responsible for:','["the provider''s power grid", "the provider''s hardware", "the provider''s buildings", "security in the cloud, such as access settings and data"]'::jsonb,3,'Customers configure their own use.','original'),
('127.689.d.6.B',3,'Who is responsible for deciding which employees can open a company''s cloud storage bucket?','["the customer", "the data center electricians", "the internet provider", "the hardware vendor"]'::jsonb,0,'Access settings belong to the customer.','original'),
('127.689.d.6.B',4,'Who is responsible for physical security of the data center buildings?','["the customer''s interns", "the cloud provider", "the customer''s website visitors", "the domain registrar"]'::jsonb,1,'Providers secure facilities.','original'),
('127.689.d.6.C',3,'The shared model reduces the risk of a stolen password leading to a breach because the customer can:','["change cable colors", "buy new servers", "enforce multi-factor authentication", "rename regions"]'::jsonb,2,'Customers control sign-in rules.','original'),
('127.689.d.6.C',4,'A common cloud threat is misconfiguration. The shared model makes it the customer''s job to:','["rewrite the internet", "rebuild the provider''s data center", "replace the provider''s hardware", "review and correct their own settings"]'::jsonb,3,'Misconfiguration is on the customer''s side.','original'),
('127.689.d.6.D',3,'When an automated security alert fires, the first step is usually to:','["review the alert details to understand what happened", "shut down the internet", "delete all data", "ignore it"]'::jsonb,0,'Understand before acting.','original'),
('127.689.d.6.D',4,'After confirming an alert is real, an admin should contain the problem, fix the cause and then:','["disable all alerts", "document what was done", "hide the alert", "blame a user"]'::jsonb,1,'Documentation supports learning.','original'),
('127.689.d.6.E',3,'An instance in the state ''pending'' is:','["being billed as terminated", "permanently deleted", "starting up and not yet ready", "fully stopped"]'::jsonb,2,'Pending precedes running.','original'),
('127.689.d.6.E',4,'An instance that has been shut down permanently and cannot be restarted is in the state:','["pending", "running", "stopping", "terminated"]'::jsonb,3,'Terminated instances are gone.','original'),
('127.689.d.6.F',3,'A normal launch sequence for an instance moves from pending to:','["running", "terminated", "shutting down", "stopped"]'::jsonb,0,'Launch ends in running.','original'),
('127.689.d.6.F',4,'To go from stopped back to running, an instance passes through:','["terminated", "pending", "archived", "deleted"]'::jsonb,1,'Starting again goes through pending.','original'),
('127.689.d.6.G',3,'For many providers, a stopped instance does not incur compute charges, but its attached storage:','["vanishes", "is free forever", "may still be billed", "becomes a printer"]'::jsonb,2,'Volumes keep costing money.','original'),
('127.689.d.6.G',4,'A running instance is billed for:','["only the time it is stopped", "only its name", "nothing at all", "the compute time it runs"]'::jsonb,3,'Running time is billable.','original'),
('127.689.d.6.H',3,'A test server is needed only during work hours. The cost-efficient plan is to:','["stop it outside work hours", "terminate it every day", "keep it running all night", "leave it pending"]'::jsonb,0,'Stopping saves compute charges.','original'),
('127.689.d.6.H',4,'A server will never be needed again. The most cost-efficient state is:','["stopped", "terminated", "running", "pending"]'::jsonb,1,'Termination removes all charges.','original'),
('127.689.d.7.A',3,'A static website is hosted by storing its HTML, CSS and image files in:','["a printer queue", "an email draft", "a storage bucket configured for website hosting", "a phone case"]'::jsonb,2,'Buckets can serve static files.','original'),
('127.689.d.7.A',4,'When setting up a static site in a bucket, the admin must set an index document, which is the:','["admin''s password", "billing address", "server''s brand", "default page visitors see first"]'::jsonb,3,'The index page is the entry point.','original'),
('127.689.d.7.B',3,'A dynamic website differs from a static website because it:','["builds pages using code and data when requested", "never changes", "has no images", "has only one page"]'::jsonb,0,'Dynamic pages are generated.','original'),
('127.689.d.7.B',4,'A site that shows each visitor their own account balance after login must be:','["static", "dynamic", "printed", "hand-delivered"]'::jsonb,1,'Personalized content needs server logic.','original'),
('127.689.d.7.C',3,'Creating a CDN distribution for a website''s bucket helps visitors worldwide get:','["more passwords", "no pages", "faster load times", "slower load times"]'::jsonb,2,'Edge caching speeds delivery.','original'),
('127.689.d.7.C',4,'After creating the distribution, the site''s address should be updated to use:','["a random number", "the old password", "a blank page", "the distribution''s domain name"]'::jsonb,3,'Traffic must flow through the CDN.','original'),
('127.689.d.7.D',3,'To launch a dynamic web server on a virtual instance, an admin installs:','["web server and application software", "music apps", "video games", "photo filters"]'::jsonb,0,'The instance needs software to run the site.','original'),
('127.689.d.7.D',4,'For visitors to reach the dynamic server, it needs a public IP address and:','["a blocked firewall", "a security rule allowing web traffic", "no network", "a dead port"]'::jsonb,1,'Network access must be opened.','original'),
('127.689.d.7.E',3,'A serverless compute function runs code:','["only on local laptops", "all day, every day", "only when triggered, without managing servers", "only on paper"]'::jsonb,2,'Serverless runs on demand.','original'),
('127.689.d.7.E',4,'With serverless compute, billing is usually based on:','["the size of the office", "the number of files in a folder", "the color of the code", "how many times and how long the function runs"]'::jsonb,3,'Pay per execution.','original'),
('127.689.d.7.F',3,'Auto scaling automatically changes the number of instances based on:','["demand", "the weather", "paper supply", "office hours"]'::jsonb,0,'Scaling follows load.','original'),
('127.689.d.7.F',4,'An auto scaling group can keep a minimum number of healthy instances by:','["turning off monitoring", "replacing instances that fail health checks", "ignoring failures", "deleting all instances"]'::jsonb,1,'Self-healing keeps capacity.','original'),
('127.689.d.7.G',3,'A launch template for auto scaling stores settings such as the instance type and:','["paper sizes", "office phone number", "the machine image to launch", "coffee orders"]'::jsonb,2,'Templates define what is launched.','original'),
('127.689.d.7.G',4,'An auto scaling group needs a minimum, a maximum and a:','["slogan", "favorite color", "guest list", "desired number of instances"]'::jsonb,3,'Capacity boundaries guide scaling.','original'),
('127.689.d.7.H',3,'A plan for monitoring an auto scaling group should include tracking:','["CPU use and instance counts", "staff birthdays", "office temperature only", "paper stock"]'::jsonb,0,'Metrics show scaling behavior.','original'),
('127.689.d.7.H',4,'Setting an alarm that triggers when CPU use stays high is part of:','["a color study", "a monitoring plan for scaling", "a fonts review", "a menu design"]'::jsonb,1,'Alarms drive scaling actions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
