from (values
('127.689.d.8.A',3,'Big data refers to data sets so large or fast-changing that they need:','["only a pencil", "a calculator only", "special tools to store and analyze them", "no storage"]'::jsonb,2,'Big data exceeds normal tools.','original'),
('127.689.d.8.A',4,'A retailer analyzing millions of purchases to stock shelves better is using big data in the:','["agriculture only", "forestry only", "none of the industries", "retail industry"]'::jsonb,3,'Retail uses data for planning.','original'),
('127.689.d.8.B',3,'A benefit of big data in healthcare is spotting:','["patterns that help predict disease outbreaks", "only logos", "only colors", "nothing useful"]'::jsonb,0,'Trends help public health.','original'),
('127.689.d.8.B',4,'A risk of collecting huge amounts of personal data is:','["lower storage costs", "privacy loss if the data is misused or breached", "fewer users", "faster typing"]'::jsonb,1,'Large data sets raise privacy stakes.','original'),
('127.689.d.8.C',3,'Blockchain makes each new block include a value from the previous block, so changing an old block would:','["fix itself", "go unnoticed", "break the chain and be noticed", "delete the network"]'::jsonb,2,'Linked hashes expose tampering.','original'),
('127.689.d.8.C',4,'In a blockchain, many participants hold copies of the ledger, which helps validate transactions because:','["only one person decides", "copies are secret", "nobody checks", "they must agree before a block is accepted"]'::jsonb,3,'Consensus ensures validity.','original'),
('127.689.d.8.D',3,'A benefit of blockchain for tracking food shipments is a:','["shared, trusted record of each step", "random guess", "erasable note", "private diary"]'::jsonb,0,'Traceability builds trust.','original'),
('127.689.d.8.D',4,'A risk of blockchain business applications is that they can:','["need no computers", "use large amounts of energy or be hard to scale", "be too transparent for laws always", "cost nothing ever"]'::jsonb,1,'Some chains are resource intensive.','original'),
('127.690.d.1.A',3,'A UX designer presenting to executives instead of to teenage users should revise the presentation to match the:','["room temperature", "font brand", "audience", "laptop model"]'::jsonb,2,'Presentations must fit who is listening.','original'),
('127.690.d.1.A',4,'A design review meant to win approval for funding differs from one meant to teach a team. The designer adjusts for each presentation''s:','["clicker brand", "file extension", "slide count rule", "purpose"]'::jsonb,3,'Purpose shapes content and tone.','original'),
('127.690.d.1.B',3,'A designer shows a chart of how many users finished checkout and explains in plain words what it means. This is:','["interpreting and communicating data clearly", "guessing outcomes", "avoiding feedback", "hiding results"]'::jsonb,0,'Data must be explained, not just shown.','original'),
('127.690.d.1.B',4,'When reporting an observation like ''three users hesitated at the Pay button,'' a designer should be:','["exaggerated", "specific and factual about what was seen", "silent", "vague"]'::jsonb,1,'Clear observations support decisions.','original'),
('127.690.d.1.C',3,'Repeating back what a user said, such as ''so the menu confused you?'', is an example of:','["interrupting", "guessing", "active listening", "multitasking"]'::jsonb,2,'Paraphrasing confirms understanding.','original'),
('127.690.d.1.C',4,'Asking a follow-up question when a user''s answer is unclear helps the designer to:','["end the interview early", "change the topic", "avoid notes", "clarify the information received"]'::jsonb,3,'Clarifying prevents misunderstandings.','original'),
('127.690.d.1.D',3,'A team designing a bank app should consider the viewpoints of both a teenager and a retired person because users can be:','["diverse in age, ability and experience", "predictable in every way", "unimportant", "identical"]'::jsonb,0,'Different users need different things.','original'),
('127.690.d.1.D',4,'Ignoring the viewpoint of users with low vision can result in a product that:','["is automatically accessible", "excludes people who cannot use it", "works for everyone", "has fewer colors by law"]'::jsonb,1,'Missing viewpoints creates barriers.','original'),
('127.690.d.1.E',3,'A UX designer who calmly explains design decisions to stakeholders and handles feedback politely is showing:','["drawing speed", "typing speed", "public relations skills", "coding speed"]'::jsonb,2,'PR skills build trust and support.','original'),
('127.690.d.1.E',4,'Sharing a project''s progress in a clear newsletter to build excitement among stakeholders is an example of:','["file compression", "coding style", "wire-framing", "public relations in UX"]'::jsonb,3,'Communication builds support for design work.','original'),
('127.690.d.2.A',3,'A current challenge in the UX field is keeping designs accessible while:','["new devices and screen sizes keep appearing", "avoiding all users", "refusing feedback", "stopping research"]'::jsonb,0,'Devices keep multiplying.','original'),
('127.690.d.2.A',4,'A trend shaping UX is the growth of voice and gesture interfaces, which means designers must plan for:','["only printed menus", "interactions that do not use a mouse or touch screen", "only paper forms", "only desktop monitors"]'::jsonb,1,'New input modes expand UX.','original'),
('127.690.d.2.B',3,'A professional who studies how people use products through interviews and surveys is a:','["network cable", "loan officer", "UX researcher", "pilot"]'::jsonb,2,'Researchers gather user insight.','original'),
('127.690.d.2.B',4,'Career roles in UX range from researcher and interaction designer to:','["only accountant", "only coder", "only janitor", "content strategist and usability tester"]'::jsonb,3,'UX has many specialties.','original'),
('127.690.d.2.C',3,'The term ''user experience'' describes:','["how a person feels and what they do when using a product", "the price of a product", "the length of a manual", "the weight of a device"]'::jsonb,0,'UX covers the whole interaction.','original'),
('127.690.d.2.C',4,'Human-centered design means designing with a strong focus on:','["the fastest shipping", "the needs and abilities of the people who will use it", "the designer''s taste only", "the cheapest materials"]'::jsonb,1,'People come first.','original'),
('127.690.d.2.D',3,'A weather app that shows the forecast for your current location is:','["irrelevant", "hostile", "relevant", "hidden"]'::jsonb,2,'Relevant means it fits the user''s need.','original'),
('127.690.d.2.D',4,'An experience that gets a task done quickly without confusion is best described as:','["random and noisy", "hidden and tricky", "slow and cluttered", "useful and friendly"]'::jsonb,3,'Useful helps; friendly is pleasant to use.','original'),
('127.690.d.2.E',3,'People tend to click the big, bright button first. This shows how behavior is influenced by:','["visual attention and psychology", "paper quality", "luck", "internet speed"]'::jsonb,0,'Psychology drives where people look and click.','original'),
('127.690.d.2.E',4,'A designer uses a familiar shopping-cart icon because users already expect it. This applies the idea that people rely on:','["random choice", "mental models from past experience", "slow typing", "bright colors only"]'::jsonb,1,'Familiar patterns reduce effort.','original'),
('127.690.d.2.F',3,'Design thinking begins by trying to understand users in a stage called:','["sell", "delete", "empathize", "publish"]'::jsonb,2,'Empathy is the first stage.','original'),
('127.690.d.2.F',4,'After brainstorming ideas, a design thinking team builds a quick model and then:','["hides the model", "stops working", "ships it untested", "tests it with users and iterates"]'::jsonb,3,'Prototype, test and refine.','original'),
('127.690.d.2.G',3,'A clear, easy-to-use ticket kiosk at a train station shows how UX design affects:','["everyday lives", "only artists", "only gamers", "only engineers"]'::jsonb,0,'Good UX makes daily tasks easier.','original'),
('127.690.d.2.G',4,'A confusing medication app could lead to mistakes, which shows that poor UX can affect:','["only logos", "people''s safety and health", "only color choice", "only fonts"]'::jsonb,1,'UX has real-world consequences.','original'),
('127.690.d.3.A',3,'Ethical use of technology includes respecting others'':','["photos for selling", "emails for forwarding", "privacy and rights", "passwords for sharing"]'::jsonb,2,'Ethics means respecting people.','original'),
('127.690.d.3.A',4,'A designer who tests a prototype with people should ethically get their:','["favorite food", "home address", "bank details", "informed consent"]'::jsonb,3,'Participants should agree knowingly.','original'),
('127.690.d.3.B',3,'For a student''s original poem and drawing, copyright law protects:','["original creative works such as art, writing and music", "any idea spoken aloud", "public street names", "simple facts only"]'::jsonb,0,'Copyright covers expression.','original'),
('127.690.d.3.B',4,'A trademark protects a brand''s name or logo, while a patent protects:','["a color scheme only", "an invention", "a recipe name", "a font style only"]'::jsonb,1,'Patents cover new inventions.','original'),
('127.690.d.3.C',3,'A designer copies a photographer''s picture into a client site without permission. This is:','["fair design", "brand building", "copyright infringement", "a patent right"]'::jsonb,2,'Using without permission infringes.','original'),
('127.690.d.3.C',4,'Selling shoes with a logo that looks almost identical to a famous brand''s logo may violate:','["copyright law only", "patent law only", "gravity", "trademark law"]'::jsonb,3,'Confusingly similar marks are infringement.','original'),
('127.690.d.3.D',3,'A student caught plagiarizing may face:','["a failing grade or other disciplinary action", "a free upgrade", "a prize", "a promotion"]'::jsonb,0,'Plagiarism has consequences.','original'),
('127.690.d.3.D',4,'For a professional designer, plagiarism could also lead to:','["higher pay", "lost clients and legal action", "better reviews", "new patents"]'::jsonb,1,'Reputation and law are at risk.','original'),
('127.690.d.3.E',3,'Using a quotation from a website in a research report requires:','["hiding the source", "deleting quotation marks", "a proper citation", "a new logo"]'::jsonb,2,'Citing credits the author.','original'),
('127.690.d.3.E',4,'When using an online photo, ethical practice is to check its license and:','["remove the creator''s name", "resell it", "claim it as your own", "give credit as required"]'::jsonb,3,'Follow license terms.','original'),
('127.690.d.4.A',3,'Qualitative data describes experiences in words, such as:','["comments users make in interviews", "the number of clicks", "the time in seconds", "the percent of users"]'::jsonb,0,'Qualitative = descriptive.','original'),
('127.690.d.4.A',4,'Quantitative data can be measured and counted, such as:','["a user''s feelings described in a story", "the percent of users who finished checkout", "an interview recording", "a user''s quote about frustration"]'::jsonb,1,'Quantitative = numbers.','original'),
('127.690.d.4.B',3,'In a user interview, a good question is open-ended, like:','["''Don''t you think the menu is clear?''", "''Is it good, yes or no?''", "''Tell me about the last time you used this site.''", "''You liked it, right?''"]'::jsonb,2,'Open questions invite detail.','original'),
('127.690.d.4.B',4,'A leading question such as ''Don''t you love this feature?'' should be avoided because it:','["improves research quality", "gets longer stories", "gets honest, unbiased answers", "pushes the user toward a particular answer"]'::jsonb,3,'Leading questions bias results.','original'),
('127.690.d.4.C',3,'A designer groups sticky-note ideas from interviews on a digital board to:','["find patterns in the feedback", "hide notes", "print posters", "delete data"]'::jsonb,0,'Organizing reveals themes.','original'),
('127.690.d.4.C',4,'Tagging interview notes in a spreadsheet by theme such as ''navigation'' or ''checkout'' makes it easier to:','["double the workload", "spot repeated problems", "avoid analysis", "lose the notes"]'::jsonb,1,'Tags surface patterns.','original'),
('127.690.d.4.D',3,'Five of six interviewed users say they could not find the search box. A reasonable conclusion is:','["interviews are useless", "the site is perfect", "the search box is hard to find", "users love search"]'::jsonb,2,'Repeated feedback signals a problem.','original'),
('127.690.d.4.D',4,'When analyzing interview data, a designer should avoid:','["taking notes", "checking multiple users", "looking for patterns", "jumping to conclusions from one comment"]'::jsonb,3,'One comment is not a pattern.','original'),
('127.690.d.4.E',3,'In a task analysis observation, a researcher watches a user try to complete a task such as:','["booking a library room online", "buying clothes without the site", "sleeping", "reading a book at home"]'::jsonb,0,'Observation shows real behavior.','original'),
('127.690.d.4.E',4,'During an observation, the researcher should document where the user pauses, makes errors and:','["what the researcher likes", "what they say while working", "the researcher''s guesses", "unrelated news"]'::jsonb,1,'Behavior and comments both matter.','original'),
('127.690.d.4.F',3,'An affinity map groups similar findings together so a team can see:','["the schedule", "the budget", "themes in the research", "the paint colors"]'::jsonb,2,'Affinity maps cluster related notes.','original'),
('127.690.d.4.F',4,'A customer journey map shows the steps a person takes and how they:','["mix colors", "write code", "pay taxes", "feel at each step"]'::jsonb,3,'Journey maps combine actions and emotions.','original'),
('127.690.d.4.G',3,'A persona is a fictional user profile based on:','["patterns found in real research", "a designer''s random guess", "nothing at all", "a celebrity"]'::jsonb,0,'Personas summarize real data.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
